using System;using System.Linq;using System.Text;using BeamScheduleFormatter;
class SlabScheduleTests {
 static string Fixture(double scale,double dx,double dy){var b=new StringBuilder("0\nSECTION\n2\nENTITIES\n");Action<double,double,string> text=(x,y,t)=>b.Append("0\nTEXT\n10\n"+((x*scale)+dx).ToString(System.Globalization.CultureInfo.InvariantCulture)+"\n20\n"+((y*scale)+dy).ToString(System.Globalization.CultureInfo.InvariantCulture)+"\n1\n"+t+"\n");text(0,15000,"SLAB SCHEDULE");text(5000,9700,"FULL LENGTH");text(11000,9700,"FULL LENGTH");text(200,8250,"S1, S5");text(3000,8000,"125");for(int n=0;n<9;n++)text(5000+n*3000,8000,n==1||n==3?"---":"#10@250 C/C");b.Append("0\nENDSEC\n0\nEOF\n");return b.ToString();}
 static void Main(){foreach(var v in new[]{new[]{1.0,0.0,0.0},new[]{2.0,100.0,-300.0}}){var rows=SlabScheduleReader.Read(Fixture(v[0],v[1],v[2]));if(rows.Count!=2||rows[0].Mark!="S1"||rows[1].Mark!="S5"||rows[0].Thickness!=125||rows[0].Bars[1]!=null||rows[0].Bars[8].SpacingMm!=250)throw new Exception("Slab DXF row/header recognition failed");}Console.WriteLine("PASS: slab DXF parser, grouped marks, blank curtailed columns and translated/scaled schedule geometry.");}
}
